import {today,dayFor,totals,shiftDate,round,nextSession} from './model.js';
import {ensureDay,assertUnchanged} from './body.js';
import {healthInsights,prepareHealthProposal,parseLocalCheckIn} from './health-intelligence.js';
import {createLifeState,factOfDay,buildCleanupPreview,classifyEmail} from './life-model.js';
import {readChatGPTLink,saveChatGPTLink} from './chatgpt-link.js';
import {parseFoodReport,searchFoods,foodById,portionNutrition,foodAction,parseAmount,defaultUnit,NUTRIENTS} from './food-lookup.js';

const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=v=>v==null?'—':Number(v).toLocaleString('en-GB',{maximumFractionDigits:1});
const dateLabel=d=>new Date(d+'T12:00:00Z').toLocaleDateString('en-GB',{day:'numeric',month:'short'});
const uuid=()=>crypto.randomUUID();
const arrow='<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="M6 18 18 6M6 6h12v12"/></svg>';
const btn=(label,action,extra='',secondary=false)=>`<button type="button" class="btn ${secondary?'secondary':''}" data-life="${action}" ${extra}>${esc(label)}</button>`;
const known=(value,suffix='')=>value==null?'Not logged':num(value)+suffix;

export function createLifeUI(ctx){
 const {store,state,render,openSheet,closeSheet,toast,wireForm,saveFooter,navigate,dateControls,nutritionHero,activity,trainingNotice,foodForm}=ctx;
 const life={data:createLifeState(),version:0,loaded:false,error:'',status:null,emails:[],syncing:false,busy:false,filter:'all',cleanupQuery:'',cleanup:null,chat:[],draft:'',image:null,proposal:null,meal:null,notifications:false,lastSync:0};
 async function api(path,options={}){
  if(!navigator.onLine)throw Error(options.method&&options.method!=='GET'?'Offline. Nothing was saved or sent. Your input has been kept.':'Offline. Reconnect to load your private records.');
  let response;try{response=await fetch('/api/'+path,{credentials:'same-origin',cache:'no-store',...options,headers:{'Content-Type':'application/json',...(options.headers||{})},signal:AbortSignal.timeout(path==='assistant'?60000:45000)});}catch{throw Error('Connection unavailable. Your input has been kept.');}
  let result;try{result=await response.json();}catch{throw Error('This feature needs the Cam’s Life service. Health history is still available.');}
  if(!response.ok)throw Error(result.message||result.error||'The request could not be completed.');return result;
 }
 const post=(path,body)=>api(path,{method:'POST',body:JSON.stringify(body)});
 async function load(){
  const results=await Promise.allSettled([api('status'),api('life')]);
  if(results[0].status==='fulfilled')life.status={...results[0].value,gmailConnected:results[0].value.gmailConnected??results[0].value.inboxConnected,hourlyEnabled:results[0].value.hourlyEnabled??results[0].value.hourlySync};
  if(results[1].status==='fulfilled'){life.data=results[1].value.state;life.version=results[1].value.version;life.loaded=true;life.error='';life.emails=(life.data.emails||[]).map(e=>({...e,...classifyEmail(e)}));}
  else life.error=results[1].reason.message;
  if(!document.querySelector('#sheet').open)render();
 }
 async function save(mutate){
  if(life.busy)throw Error('A save is already in progress.');if(!life.loaded)throw Error(life.error||'Private storage is connecting. Try again shortly.');
  life.busy=true;const next=structuredClone(life.data);
  try{mutate(next);const result=await api('life',{method:'PUT',body:JSON.stringify({state:next,version:life.version})});life.data=result.state;life.version=result.version;life.error='';render();}
  catch(e){life.error=e.message;if(/changed|conflict/i.test(e.message))await load();throw e;}finally{life.busy=false;}
 }
 function empty(title,copy,action=''){return `<div class="empty"><h3>${esc(title)}</h3><p>${esc(copy)}</p>${action}</div>`;}
 function notice(){return life.error?`<div class="notice warning" role="status"><div><b>Life sync needs attention</b><p>${esc(life.error)}</p></div>${btn('Retry','reload','',true)}</div>`:'';}
 function factCard(compact=false){const fact=factOfDay(state.date),saved=life.data.favorites.includes(fact.id);return `<article class="fact-card ${compact?'compact':''}"><div class="card-kicker"><span class="eyebrow">FACT OF THE DAY</span></div><h2>${esc(fact.title)}</h2><p>${esc(fact.text||fact.body)}</p><div class="fact-footer"><a href="${esc(fact.sourceURL||fact.sourceUrl)}" target="_blank" rel="noopener noreferrer">${esc(fact.source||fact.sourceTitle||'Read the source')} ${arrow}</a><button class="textbtn" data-life="favorite" data-id="${esc(fact.id)}" aria-pressed="${saved}">${saved?'Saved ✓':'Save fact'}</button></div></article>`;}
 function taskRows(limit){const tasks=life.data.tasks.filter(t=>t.status!=='done').slice(0,limit??100);return tasks.length?tasks.map(t=>`<div class="task-row"><button class="task-check" data-life="task-toggle" data-id="${esc(t.id)}" aria-label="Complete ${esc(t.title)}">✓</button><div><b>${esc(t.title)}</b><small>${t.dueDate?dateLabel(t.dueDate):t.dueAt?esc(t.dueAt):'No deadline'}${t.source==='email'?' · From your inbox':''}</small></div>${t.sourceEmailId?`<a href="https://mail.google.com/mail/u/0/#all/${encodeURIComponent(t.sourceEmailId)}" target="_blank" rel="noopener noreferrer" aria-label="Open source email">${arrow}</a>`:''}</div>`).join(''):empty('No open to-dos','Add a to-do or scan Gmail for actions.');}
 function privateUnavailable(){return empty('Private records unavailable',navigator.onLine?'Reconnect private storage to load your to-dos and deliveries.':'Reconnect to load your to-dos and deliveries. Nothing is shown as completed or cleared.');}
 function deliveryCard(d){const done=['picked_up','delivered','cancelled'].includes(d.status);const statusLabel=d.status==='picked_up'?'Picked up':d.status==='delivered'?'Delivered':d.status==='cancelled'?'Cancelled':d.status==='ready_for_pickup'?'Ready to collect':d.status==='in_transit'?'On the way':d.status==='ordered'?'Ordered':'Expected';return `<article class="delivery-card ${done?'complete':''}"><div class="card-kicker"><span class="eyebrow">${esc(d.carrier||d.sender||'Delivery')}</span><span class="tag ${done?'green':''}">${esc(statusLabel)}</span></div><h3>${esc(d.title||d.name||'Your package')}</h3><p>${esc(d.location||d.pickupLocation||d.trackingNumber||'Details from your delivery email')}</p>${d.pickupCode?`<div class="pickup-code"><span>PICKUP CODE</span><button class="pickup-code-value" data-life="copy-code" data-code="${esc(d.pickupCode)}" title="Copy pickup code">${esc(d.pickupCode)}</button></div>`:''}<div class="delivery-footer"><span>${d.deadline||d.pickupDeadline?'Collect by '+esc(d.deadline||d.pickupDeadline):d.expectedDate?'Expected '+esc(d.expectedDate):'No date confirmed'}</span>${btn(done?'Undo':'Picked up ✓','delivery-toggle',`data-id="${esc(d.id)}"`,true)}</div></article>`;}
 function overview(){
  const d=dayFor(store.data,state.date),t=totals(d),p=store.data.profile.targets,hasFood=d.food.length>0;
  const pending=life.loaded?life.data.tasks.filter(t=>t.status!=='done').length:null,packages=life.loaded?life.data.deliveries.filter(d=>!['picked_up','delivered','cancelled'].includes(d.status)).length:null;
  const progress=p.kcal&&hasFood?Math.max(0,Math.min(100,t.kcal/p.kcal*100)):0;
  const recent=Object.keys(store.data.days).filter(date=>date<state.date&&store.data.days[date].food.length).sort().at(-1);
  const remaining=hasFood&&p.kcal!=null&&!t.missing.kcal?p.kcal-t.kcal:null;
  return `<div class="today-greeting"><div><h1>Your day</h1></div>${btn('Check in','ask')}</div>${dateControls()}${notice()}
   <section class="day-fuel"><div class="card-kicker"><span class="eyebrow">FOOD LOG</span><span class="tag">${hasFood?t.pending?'Partial nutrition':t.estimated?'Includes estimates':'Logged today':'Not logged'}</span></div>
    <div class="fuel-main"><div><span class="caption">Calories logged</span><strong>${hasFood?num(t.kcal):'—'}<small>kcal${t.missing.kcal?' + ?':''}</small></strong><p>${remaining!=null?num(Math.abs(remaining))+' kcal '+(remaining<0?'above target':'to target'):hasFood?'Known subtotal':'No food logged yet'}</p></div></div>
    <div class="fuel-bar" role="img" aria-label="${hasFood?Math.round(progress)+'% of calorie target logged':'No food logged'}"><i style="width:${progress}%"></i></div>
    <div class="fuel-footer"><span>${p.kcal?num(p.kcal)+' kcal daily target':'No calorie target set'}</span><button class="textbtn" data-act="food-log">Log a meal ${arrow}</button></div></section>
   ${activity(d)}${!hasFood&&recent?`<button class="last-log" data-date="${recent}"><span><b>Last food log</b><small>${dateLabel(recent)} · ${num(totals(dayFor(store.data,recent)).kcal)} kcal logged</small></span>${arrow}</button>`:''}
   <div class="life-overview">${[['Open to-dos',pending,'Things to do'],['On the way',packages,'Packages expected']].map(([label,value,sub])=>`<button class="life-metric" data-view="life"><span class="eyebrow">${label}</span><strong>${num(value)}</strong><small>${sub}${arrow}</small></button>`).join('')}</div>
   <section class="life-section"><div class="section-head"><h2>To-dos</h2><button class="textbtn" data-view="life">View all ${arrow}</button></div><div class="life-card task-preview">${life.loaded?taskRows(3):privateUnavailable()}<div class="card-bottom">${btn('Add a to-do','task-add','',true)}${btn('Scan Gmail','inbox-sync','',true)}</div></div></section>
   ${packages?`<section class="life-section"><div class="section-head"><h2>Expected deliveries</h2></div>${life.data.deliveries.filter(d=>!['picked_up','delivered','cancelled'].includes(d.status)).slice(0,2).map(deliveryCard).join('')}</section>`:''}
   <section class="life-card next-session"><span class="eyebrow">NEXT SESSION</span><button data-view="training"><span><b>${esc(nextSession(store.data,state.date)?.name||'No session set')}</b><small>${d.workouts.length?d.workouts.map(w=>esc(w.name)).join(', ')+' logged':'Your prescribed session'}</small></span>${arrow}</button></section>${factCard(true)}`;
 }
 function healthTabs(){return `<nav class="health-tabs" aria-label="Health sections">${[['nutrition','Food & activity'],['training','Training'],['body','Body'],['insights','Trends & insights']].map(([view,label])=>`<button data-view="${view}" class="${state.view===view?'active':''}" ${state.view===view?'aria-current="page"':''}>${label}</button>`).join('')}<button data-life="wellbeing">Check in</button></nav>`;}
 function wellbeingCard(){const d=dayFor(store.data,state.date),w=d.wellbeing||{};return `<section class="life-card"><div class="section-head"><h2>Daily check-in</h2>${btn('Check in','wellbeing','',true)}</div><div class="wellbeing-grid"><div><span>Mood</span><b>${w.mood?['','Low','Flat','Okay','Good','Great'][w.mood]:'—'}</b></div><div><span>Energy</span><b>${w.energy?num(w.energy)+' / 5':'—'}</b></div><div><span>Sleep</span><b>${known(w.sleepHours,' h')}</b></div><div><span>Muscle</span><b>${known(d.body?.skeletalMuscleKg,' kg')}</b></div></div>${w.feelings?`<p>${esc(w.feelings)}</p>`:''}</section>`;}
 function simpleChart(series,label,unit){if(!series.length)return empty('No '+label.toLowerCase()+' readings yet.','Only real check-ins appear here.');const values=series.map(p=>p.value),min=Math.min(...values),max=Math.max(...values),span=max-min||1,points=series.map((p,i)=>`${20+(series.length===1?.5:(Date.parse(p.date)-Date.parse(series[0].date))/(Date.parse(series.at(-1).date)-Date.parse(series[0].date)))*620},${160-(p.value-min)/span*120}`);return `<figure class="life-chart"><svg viewBox="0 0 660 200" role="img" aria-label="${esc(label)} from ${esc(series[0].date)} to ${esc(series.at(-1).date)}"><line x1="20" y1="160" x2="640" y2="160" stroke="var(--border)"/><polyline points="${points.join(' ')}" fill="none" stroke="var(--accent)" stroke-width="3"/>${series.map((p,i)=>`<circle cx="${points[i].split(',')[0]}" cy="${points[i].split(',')[1]}" r="4" fill="var(--accent)"><title>${p.date}: ${p.value} ${unit}</title></circle>`).join('')}</svg><figcaption><span>${dateLabel(series[0].date)} · ${num(series[0].value)} ${unit}</span><span>${dateLabel(series.at(-1).date)} · ${num(series.at(-1).value)} ${unit}</span></figcaption><details><summary>View recorded values</summary><table><thead><tr><th>Date</th><th>${esc(label)}</th></tr></thead><tbody>${series.map(p=>`<tr><td>${p.date}</td><td>${num(p.value)} ${unit}</td></tr>`).join('')}</tbody></table></details></figure>`;}
 function insights(){const days=Object.entries(store.data.days).filter(([d])=>d<=state.date&&d>=shiftDate(state.date,-29)).sort(([a],[b])=>a.localeCompare(b)),weight=days.filter(([,d])=>d.weightKg!=null).map(([date,d])=>({date,value:d.weightKg})),muscle=days.filter(([,d])=>d.body?.skeletalMuscleKg!=null).map(([date,d])=>({date,value:d.body.skeletalMuscleKg})),ins=healthInsights(store.data,state.date);const entries=Array.isArray(ins)?ins:ins.insights||ins.cards||[];return `${dateControls()}<div class="page-intro"><div><span class="eyebrow">THE BIGGER PICTURE</span><h1>Trends & insights</h1><p>Recorded values, your chosen targets, and honest gaps.</p></div>${btn('Ask about my progress','ask')}</div><div class="life-grid"><section class="life-card"><div class="section-head"><h2>Weight · last 30 days</h2><span class="tag">${weight.length} readings</span></div>${simpleChart(weight,'Weight','kg')}<div class="section-head"><h2>Skeletal muscle</h2><span class="tag">WATCH / SCALE</span></div>${simpleChart(muscle,'Muscle','kg')}</section><section class="life-card"><span class="eyebrow">RESULTS & EXPECTATIONS</span><h2>What your logs can tell us</h2>${entries.length?entries.map(i=>`<article class="insight-item"><h3>${esc(i.title||i.label||'Your trend')}</h3><p>${esc(i.text||i.detail||i.message||i.description)}</p></article>`).join(''):`<p>${esc(ins.summary||'More consistent check-ins will make patterns clearer. A partial food log is not a full day’s intake.')}</p>`}${ins.weightTrend?.projection?`<article class="insight-item"><h3>Two-week projection · estimate</h3><p>${num(ins.weightTrend.projection.value)} kg around ${dateLabel(ins.weightTrend.projection.date)} if the recent observed trend continues.</p></article>`:''}<p class="help">Trends describe logs. Forecasts need enough dated readings, and are estimates rather than promises.</p>${btn('Discuss in ChatGPT','chatgpt','',true)}</section></div>${wellbeingCard()}`;}
 function inbox(){const digest=life.data.lastDigest,shown=life.emails.filter(e=>life.filter==='all'||e.category===life.filter||life.filter==='unread'&&e.unread);return `<div class="page-intro"><div><span class="eyebrow">YOUR ATTENTION, BACK</span><h1>Inbox</h1><p>Unread mail, actions and delivery updates.</p></div>${btn(life.syncing?'Scanning…':'Scan Gmail','inbox-sync',life.syncing?'disabled':'')}</div>${notice()}<div class="inbox-toolbar"><div class="segmented">${[['all','All'],['unread','Unread'],['action','Needs you'],['noise','Noise']].map(([key,label])=>`<button data-life="inbox-filter" data-filter="${key}" class="${life.filter===key?'selected':''}">${label}</button>`).join('')}</div><div>${btn(life.status?.gmailConnected?'Gmail connected':'Connect Gmail','gmail-connect','',true)}${btn('Notifications','notifications','',true)}</div></div><div class="life-grid"><section><div class="life-card inbox-digest"><span class="eyebrow">YOUR LATEST BRIEF</span><h2>${digest?'Latest summary':'No summary yet'}</h2><p>${esc(digest?.summary||(digest?`${digest.total} messages reviewed. ${digest.counts.action} need attention, ${digest.counts.noise} look like noise.`:null)||'Scan your mailbox to collect action items, delivery updates, and a short digest.')}</p>${digest?.generatedAt?`<small>Updated ${esc(new Date(digest.generatedAt).toLocaleString('en-GB'))}</small>`:''}<p class="help">${life.status?.hourlyEnabled?'Hourly summaries are enabled.':'Hourly Gmail briefs are enabled in ChatGPT. This app’s mailbox view refreshes when you scan after Google sign-in setup.'}</p></div><div class="section-head"><h2>Mail to review</h2><span>${shown.length} loaded</span></div><div class="life-card inbox-list">${shown.length?shown.map(e=>`<a class="inbox-row ${e.unread?'unread':''}" href="https://mail.google.com/mail/u/0/#all/${encodeURIComponent(e.id)}" target="_blank" rel="noopener noreferrer"><span class="mail-avatar">${esc((e.fromName||e.from||'?')[0].toUpperCase())}</span><div><b>${esc(e.subject||'(No subject)')}</b><span>${esc(e.fromName||e.from)}</span><p>${esc(e.snippet||'')}</p></div><small>${esc(e.category||'update')} ${arrow}</small></a>`).join(''):empty('No mail loaded yet.','Connect Gmail, then scan. Your mailbox stays in Gmail.')}</div></section><section class="life-card cleanup-card"><span class="eyebrow">LET IT GO</span><h2>Mailbox cleanup</h2><form id="cleanup-form"><label class="field">What can go?<textarea name="query" rows="3" maxlength="400" placeholder="Delete unread Codex auto-review notifications">${esc(life.cleanupQuery)}</textarea></label><div class="cleanup-examples">${['Codex auto review','Newsletters','GitHub notifications'].map(q=>`<button type="button" class="tag" data-life="cleanup-example" data-query="${q}">${q}</button>`).join('')}</div><button class="btn full" type="submit">Find matches to review</button></form><p class="help">You review the exact messages first. Trash is recoverable in Gmail for 30 days; nothing is permanently deleted here.</p>${life.status?.gmailConnected?btn('Disconnect Gmail','gmail-disconnect','',true):''}</section></div>`;}
 function lifeView(){if(!life.loaded)return `<div class="page-intro"><div><h1>Life</h1><p>To-dos, packages and pickup codes.</p></div></div>${notice()}<section class="life-card">${privateUnavailable()}</section>${factCard()}`;const done=life.data.tasks.filter(t=>t.status==='done'),deliveries=life.data.deliveries;return `<div class="page-intro"><div><span class="eyebrow">MAKE SPACE</span><h1>Life</h1><p>To-dos, packages and pickup codes.</p></div>${btn('Add a to-do','task-add')}</div>${notice()}<div class="life-grid"><section><div class="section-head"><h2>Your to-do list</h2><span class="tag">${life.data.tasks.length-done.length} open</span></div><div class="life-card">${taskRows()}${done.length?`<details class="completed-tasks"><summary>${done.length} completed</summary>${done.map(t=>`<div class="task-row complete"><button class="task-check" data-life="task-toggle" data-id="${esc(t.id)}" aria-label="Reopen ${esc(t.title)}">✓</button><b>${esc(t.title)}</b></div>`).join('')}</details>`:''}</div><div class="section-head"><h2>Deliveries & pickup</h2>${btn('Add package','delivery-add','',true)}</div><div class="delivery-list">${deliveries.length?deliveries.map(deliveryCard).join(''):`<div class="life-card">${empty('Nothing on the way yet.','Scan Gmail to discover delivery emails, or add a package yourself.',btn('Scan Gmail','inbox-sync','',true))}</div>`}</div></section><section>${factCard()}<div class="life-card"><span class="eyebrow">YOUR COLLECTION</span><h3>${life.data.favorites.length} saved facts</h3><p>Save the facts you want to come back to.</p>${btn('View saved facts','saved-facts','',true)}</div></section></div>`;}
 function ask(){return `<div class="page-intro"><div><span class="eyebrow">YOUR WORDS → YOUR LIFE</span><h1>Check in</h1><p>Describe your meal. Nutrition fills in here.</p></div>${btn('Deeper help','chatgpt','',true)}</div><div class="assistant-layout"><section class="assistant-main life-card"><div class="chat-stream" aria-live="polite">${life.chat.length?life.chat.map(m=>`<article class="chat-bubble ${m.role}"><span>${m.role==='user'?'YOU':'CAM’S LIFE'}</span><p>${esc(m.text)}</p></article>`).join(''):`<div class="assistant-welcome"><h2>What would you like to log?</h2><p>Try: I ate 200 g cooked chicken breast and 150 g cooked rice.</p><p class="help">Food lookup happens in this app. Adjust the portions, then save to your diary.</p></div>`}${life.busy?'<div class="chat-bubble assistant"><span>CAM’S LIFE</span><p>Saving your check-in…</p></div>':''}${mealReview()}${life.proposal&&!life.meal?`<div class="ai-proposal"><span class="eyebrow">REVIEW BEFORE SAVING · ${life.proposal.date}</span><h3>Here’s what I understood.</h3><ul class="proposal-list">${life.proposal.changes.map(c=>`<li><b>${esc(c.label||c.path)}</b><span>${esc(typeof c.after==='object'?JSON.stringify(c.after):c.after??'Unknown')}</span></li>`).join('')}</ul><p class="help">Nutrition can be estimated. Watch body composition is an estimate. Your health records are saved in your public GitHub repository.</p>${btn('Save to diary','proposal-save')}${btn('Dismiss','proposal-dismiss','',true)}</div>`:''}</div><form class="composer" id="assistant-form"><label class="sr-only" for="assistant-message">Your check-in</label><textarea id="assistant-message" name="message" rows="3" maxlength="8000" placeholder="I ate… My watch says… Today I feel…">${esc(life.draft)}</textarea>${life.image?`<div class="attachment-preview"><img src="${life.image}" alt="Check-in photo attachment"><span>Attached for this request only</span>${btn('Remove','photo-remove','',true)}</div>`:''}<div class="composer-actions"><label class="btn secondary file-label">+ Photo<input id="checkin-photo" type="file" accept="image/jpeg,image/png,image/webp" hidden></label><small>Free food lookup · stays in the app</small><button class="btn" type="submit" ${life.busy?'disabled':''}>Send ${arrow}</button></div></form></section><aside class="assistant-aside"><div class="life-card"><span class="eyebrow">ONE CONVERSATION</span><h3>Quick prompts</h3><div class="prompt-chips">${[['Log my food','I ate '],['Watch check-in','My watch says '],['Review my progress','What trends can you see in my recent logs?'],['How I feel','Today I feel ']].map(([label,prompt])=>`<button data-life="prompt" data-prompt="${esc(prompt)}">${label} ${arrow}</button>`).join('')}</div><p class="help">Food values come from USDA data and your saved recipes. Oil and sauces need their own entries. Deeper help opens ChatGPT separately; photo analysis is not automatic.</p></div>${wellbeingCard()}</aside></div>`;}
 function setupBlock(){return `<section class="life-card"><span class="eyebrow">YOUR CONNECTIONS</span><h2>Connections</h2><div class="setup-grid"><div><b>ChatGPT · your subscription</b><p>Common check-ins work on your device. Copy a deeper question into ChatGPT for reasoning or photo analysis, then use your connected GitHub to save.</p>${btn('Open ChatGPT handoff','chatgpt','',true)}</div><div><b>Gmail</b><p>${life.status?.gmailConnected?'Connected. Scan for actions and deliveries.':'Google OAuth setup is needed before the secure connection can open.'}</p>${btn('Connect Gmail','gmail-connect','',true)}</div></div></section>`;}
 function wellbeingForm(){const date=state.date,d=dayFor(store.data,date),baseline=structuredClone(d.wellbeing),bodyBase=d.body?.skeletalMuscleKg;openSheet('Daily check-in',`<form><p class="help">For ${dateLabel(date)}. Leave unmeasured values blank.</p><div class="form-grid">${[['mood','Mood','Low','Flat','Okay','Good','Great'],['energy','Energy','Very low','Low','Okay','Good','High']].map(([key,label,...values])=>`<label class="field">${label}<select name="${key}"><option value="">Not logged</option>${values.map((v,i)=>`<option value="${i+1}" ${d.wellbeing?.[key]===i+1?'selected':''}>${v}</option>`).join('')}</select></label>`).join('')}<label class="field">Sleep (hours)<input name="sleepHours" type="number" min="0" max="24" step="0.1" value="${d.wellbeing?.sleepHours??''}"></label><label class="field">Skeletal muscle (kg)<input name="skeletalMuscleKg" type="number" min="0.1" max="250" step="0.1" value="${bodyBase??''}" placeholder="From your watch or scale"></label></div><label class="field">Feelings<textarea name="feelings" maxlength="2000">${esc(d.wellbeing?.feelings)}</textarea></label><p class="help">These health entries use your existing public repository. Keep private personal details out of this field.</p>${saveFooter('Save check-in')}</form>`,()=>wireForm(async fd=>store.save(data=>{const day=ensureDay(data,date);assertUnchanged(day.wellbeing,baseline);assertUnchanged(day.body?.skeletalMuscleKg,bodyBase);day.wellbeing={...day.wellbeing,mood:fd.get('mood')?Number(fd.get('mood')):null,energy:fd.get('energy')?Number(fd.get('energy')):null,sleepHours:fd.get('sleepHours')!==''?Number(fd.get('sleepHours')):null,feelings:String(fd.get('feelings'))};if(fd.get('skeletalMuscleKg')!==''||bodyBase!=null)day.body={...day.body,skeletalMuscleKg:fd.get('skeletalMuscleKg')!==''?Number(fd.get('skeletalMuscleKg')):null,recordedAt:new Date().toISOString()};},'Save daily wellbeing and muscle check-in')));}
 function taskForm(){openSheet('Add a to-do',`<form id="life-task-form"><label class="field">To-do<input name="title" required maxlength="300" placeholder="Pick up my package"></label><label class="field">Due date (optional)<input name="dueDate" type="date"></label><p class="form-error" role="alert"></p><button class="btn" type="submit">Add to-do</button></form>`,()=>document.querySelector('#life-task-form').addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData(e.target),b=e.target.querySelector('button');b.disabled=true;try{await save(s=>s.tasks.push({id:uuid(),title:String(fd.get('title')),dueDate:fd.get('dueDate')||null,status:'open',source:'manual',createdAt:new Date().toISOString()}));closeSheet(true);toast('To-do saved.');}catch(err){e.target.querySelector('.form-error').textContent=err.message;}finally{b.disabled=false;}}));}
 function deliveryForm(){openSheet('Add a delivery',`<form id="life-delivery-form"><label class="field">Package<input name="title" required maxlength="300" placeholder="My order"></label><div class="form-grid">${[['carrier','Carrier'],['trackingNumber','Tracking number'],['pickupCode','Pickup code'],['pickupLocation','Pickup location']].map(([key,label])=>`<label class="field">${label}<input name="${key}" maxlength="200"></label>`).join('')}<label class="field">Collect by<input type="date" name="pickupDeadline"></label></div><p class="form-error" role="alert"></p><button class="btn" type="submit">Save package</button></form>`,()=>document.querySelector('#life-delivery-form').addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData(e.target),b=e.target.querySelector('button');b.disabled=true;try{await save(s=>s.deliveries.push({id:uuid(),...Object.fromEntries([...fd].map(([k,v])=>[k,String(v).trim()||null])),status:fd.get('pickupCode')?'ready_for_pickup':'ordered',createdAt:new Date().toISOString(),source:'manual'}));closeSheet(true);toast('Package saved.');}catch(err){e.target.querySelector('.form-error').textContent=err.message;}finally{b.disabled=false;}}));}
 function chatGPTHandoff(){const prompt=`Help me with Cam’s Life. The repository is CameronNel/Cam-s-Health. Read AGENTS.md and the latest dist/data/health.json through GitHub before logging. Preserve all existing records, validate changes, commit only my actual requested entries, and verify them after saving. My selected date is ${state.date}. ${life.draft||life.lastCheckIn||'Please review my recent health logs, trends, concerns, and next useful check-in.'}\nIf analyzing a photo, I will attach it here. Ask about unknown quantities; never infer body fat from photos.`;const link=readChatGPTLink();openSheet('Continue with your ChatGPT subscription',`<p class="help">Copy your prompt, open ChatGPT, and paste it. This uses ChatGPT separately, with no paid API. Attach your photo there if needed.</p><label class="field">Your prompt<textarea id="handoff-prompt" rows="8" readonly>${esc(prompt)}</textarea></label>${btn('Copy prompt','copy-handoff')}<a class="btn secondary" id="chatgpt-open-link" href="${esc(link)}" target="_blank" rel="noopener noreferrer">Open ChatGPT</a><details class="disclosure"><summary>Use a dedicated Cam’s Life chat</summary><form id="chatgpt-link-form"><label class="field">ChatGPT conversation or project link<input name="url" type="url" maxlength="1000" value="${link==='https://chatgpt.com/'?'':esc(link)}" placeholder="https://chatgpt.com/c/…"></label><p class="help">Paste your own chat or project URL. This preference stays on this device. Leave blank to open ChatGPT home.</p><button type="submit" class="btn secondary">Save chat link</button><p class="form-error" role="alert"></p></form></details><p class="help">ChatGPT needs its GitHub connection to update your health record. Return here and refresh after a verified save. Nothing has been logged or sent by opening this sheet. Embedded ChatGPT plan usage for hosted apps needs separate access approval.</p>`,()=>document.querySelector('#chatgpt-link-form').addEventListener('submit',e=>{e.preventDefault();try{const url=saveChatGPTLink(new FormData(e.target).get('url'));document.querySelector('#chatgpt-open-link').href=url;toast('ChatGPT destination saved on this device.');e.target.querySelector('.form-error').textContent='';}catch(err){e.target.querySelector('.form-error').textContent=err.message;}}));}
 async function sync(){if(life.syncing)return;life.syncing=true;render();try{const result=await post('inbox/sync',{});life.emails=(result.state?.emails||result.emails||[]).map(e=>({...e,...classifyEmail(e)}));life.lastSync=Date.now();await load();if(life.notifications&&Notification.permission==='granted')new Notification('Cam’s Life · inbox updated',{body:`${life.data.tasks.filter(t=>t.status!=='done').length} open to-dos. ${life.data.deliveries.filter(d=>d.status==='ready_for_pickup').length} pickups ready.`});toast('Inbox scanned. Deliveries and to-dos updated.');}catch(e){life.error=e.message;toast(e.message);}finally{life.syncing=false;render();}}
 async function cleanup(query){life.cleanupQuery=query;const preview=buildCleanupPreview(life.emails,query),items=preview.emails||preview.messages||preview.matches||preview.candidates||[];const ids=preview.messageIds||preview.ids||items.map(e=>e.id);if(!ids.length){toast(preview.unsupportedReason||preview.message||'No supported matches in the loaded mail. Scan unread mail first.');return;}const chosen=life.emails.filter(e=>ids.includes(e.id));openSheet('Review messages to clear',`<p class="help">${chosen.length} exact messages match “${esc(query)}”. Choose an action, then confirm.</p><div class="cleanup-review">${chosen.map(e=>`<label class="inbox-row"><input type="checkbox" name="cleanup-id" value="${esc(e.id)}" checked><span><b>${esc(e.subject)}</b><small>${esc(e.from)}</small></span></label>`).join('')}</div><label class="field">Action<select id="cleanup-operation"><option value="trash">Move to Trash</option><option value="archive">Archive</option><option value="read">Mark read</option></select></label><p id="cleanup-error" class="form-error" role="alert"></p>${btn('Confirm for selected messages','cleanup-apply')}`);}
 async function send(form){
  if(life.busy)return;
  const message=new FormData(form).get('message').trim();if(!message&&!life.image)return;
  life.draft=message;life.lastCheckIn=message;life.chat.push({role:'user',text:message||'Photo attached.'});
  try{
   const amount=parseAmount(message),onlyAmount=amount&&/^(?:\s*(?:raw|cooked|grilled|roasted|boiled|dry)[ .]*)?$/i.test(amount.rest);
   if(life.meal&&onlyAmount){
    const missing=life.meal.items.filter(item=>!item.amount);
    if(missing.length===1){const item=missing[0],food=foodById(item.foodId,store.data),u=defaultUnit(food,amount.unit,item.query);item.amount=u?amount.amount:null;item.unit=u||'g';item.needsWeight=!u;compileMeal();life.draft='';life.chat.push({role:'assistant',text:life.proposal?'Portion filled in. Your meal is ready to save.':'Check the portion below; nothing has been saved yet.'});}
    else life.chat.push({role:'assistant',text:'Set the amount next to each food below so I know which portion you mean.'});
    render();return;
   }
   const result=parseLocalCheckIn(message),items=parseFoodReport(message,store.data),replacing=!!life.meal;
   if(life.meal&&items.length===1&&!/\b(?:ate|had|log|eaten)\b/i.test(message)){
    const incoming=items[0],existing=life.meal.items.find(item=>item.foodId&&item.foodId===incoming.foodId||item.query.toLowerCase()===incoming.query.toLowerCase());
    if(existing){Object.assign(existing,incoming);compileMeal();life.draft='';life.chat.push({role:'assistant',text:life.proposal?'Updated that portion. Your whole meal is ready to save.':'Updated that food. Check the remaining portions below.'});render();return;}
   }
   if(items.length){
    life.meal={date:state.date,items:items.map(item=>({...item,entryId:'food-'+uuid()})),baseActions:result.actions.filter(a=>a.type!=='add_food'),error:''};compileMeal();
    life.chat.push({role:'assistant',text:`Found ${items.length} ${items.length===1?'food':'foods'}. ${life.proposal?'Nutrition is filled in below.':'Check the matches and enter your portions below.'} ${replacing?'This replaces your previous unsaved review. ':''}Save to diary when it looks right.`});
    for(const question of result.questions||[])if(!question.startsWith('Nutrition for'))life.chat.push({role:'assistant',text:question});
    life.draft='';
   }else if(result.actions.length){
    life.meal=null;life.proposal={...prepareHealthProposal(store.data,state.date,result.actions),date:state.date};life.draft='';
    life.chat.push({role:'assistant',text:'Your check-in is filled in below. Save it to your diary when it looks right.'});
    for(const question of result.questions||[])life.chat.push({role:'assistant',text:question});
   }else if(/trend|progress|insight|concern|predict/i.test(message)){
    const insights=healthInsights(store.data,state.date);life.chat.push({role:'assistant',text:insights.insights.map(i=>i.title+': '+i.detail).join('\n\n')+'\n\nThese are calculations from your logs. Deeper help opens ChatGPT separately.'});
   }else if(message){
    life.chat.push({role:'assistant',text:'Try “I ate 200 g chicken breast and 150 g rice”, or name a food such as “chicken breast”. I’ll fill nutrition here and ask for the portion.'});
   }
   if(life.image)life.chat.push({role:'assistant',text:'I can log the foods described in your text here. Reading the attached photo requires opening ChatGPT separately; the photo has not been sent or stored.'});
  }catch(e){life.chat.push({role:'assistant',text:e.message});}
  render();if(life.meal)document.querySelector('.meal-review')?.scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});else document.querySelector('.chat-stream')?.scrollTo({top:999999,behavior:'smooth'});
 }
 function compileMeal(){
  if(!life.meal)return;
  life.proposal=null;life.meal.error='';
  if(life.meal.items.some(item=>portionNutrition(item,store.data).error))return;
  try{const actions=[...life.meal.items.map(item=>({...foodAction(item,store.data),id:item.entryId})),...life.meal.baseActions];life.proposal={...prepareHealthProposal(store.data,life.meal.date,actions),date:life.meal.date};}
  catch(e){life.meal.error=e.message;}
 }
 function nutrientRow(values,label='Portion nutrition'){return `<div class="meal-nutrients" aria-label="${esc(label)}">${[['kcal','kcal'],['protein','protein'],['carbs','carbs'],['fat','fat']].map(([key,name])=>`<div><b>${num(values?.[key])}${key==='kcal'?'':'<small> g</small>'}</b><span>${name}</span></div>`).join('')}</div>`;}
 function mealItem(item,index){
  const p=portionNutrition(item,store.data),food=p.food,choices=[...(item.choices||[])];if(food&&!choices.some(f=>f.id===food.id))choices.unshift(food);
  return `<article class="meal-item" data-meal-index="${index}"><header><h3>${esc(item.query)}</h3>${btn('Remove','meal-remove',`data-index="${index}"`,true)}</header><label class="field">Food match<select data-meal-field="foodId" data-index="${index}" aria-label="Food match for ${esc(item.query)}"><option value="">Choose a match</option>${choices.map(f=>`<option value="${esc(f.id)}" ${f.id===item.foodId?'selected':''}>${esc(f.name)}</option>`).join('')}</select></label>${!food?`<div class="meal-search"><label class="field">Search food<input data-meal-query="${index}" value="${esc(item.query)}" maxlength="200" placeholder="e.g. chicken breast"></label>${btn('Find matches','meal-search',`data-index="${index}"`,true)}</div><p class="help">${choices.length?'Choose the food that fits your meal.':'No matching nutrition found. Try a simpler name or enter its label.'}</p>${btn('Enter a label','meal-label',`data-index="${index}"`,true)}${btn('Keep nutrition unknown','meal-unknown',`data-index="${index}"`,true)}`:''}<div class="form-grid meal-portion"><label class="field">Your portion<input data-meal-field="amount" data-index="${index}" type="number" inputmode="decimal" min="0.01" max="10000" step="any" value="${item.amount??''}" placeholder="How much?" aria-label="Portion for ${esc(item.query)}"></label><label class="field">Unit<select data-meal-field="unit" data-index="${index}" aria-label="Unit for ${esc(item.query)}">${[['g','grams'],['kg','kilograms'],['oz','ounces'],['lb','pounds'],...(food?.portions||[]).map(v=>[v.id,v.label+' ('+num(v.grams)+' g)'])].map(([key,label])=>`<option value="${esc(key)}" ${item.unit===key?'selected':''}>${esc(label)}</option>`).join('')}</select></label></div><div class="meal-preview">${mealPreview(item)}</div></article>`;
 }
 function mealPreview(item){const p=portionNutrition(item,store.data);return `${nutrientRow(p.nutrients||p.food?.per100g,p.nutrients?'Portion nutrition':'Nutrition per 100 grams')}<p class="help meal-basis">${p.nutrients?esc(p.quantity)+' · '+(p.food.estimated?'estimated nutrition':'nutrition unknown'):p.food?'Per 100 g. Enter your portion to calculate its nutrition.':'Select a food before calculating nutrition.'}</p>${p.error&&item.amount!=null?`<p class="form-error">${esc(p.error)}</p>`:''}${item.needsWeight?'<p class="help">That food count has no reliable gram weight. Weigh your portion or choose a listed measure.</p>':''}${p.food?`<p class="help">${p.food.url?`<a href="${esc(p.food.url)}" target="_blank" rel="noopener noreferrer">${esc(p.food.source)}</a>`:esc(p.food.source)}${p.food.source.startsWith('USDA')?' · Oil and sauces are separate.':''}</p>`:''}`;}
 function mealFooter(){
  const items=life.meal.items.map(item=>portionNutrition(item,store.data)),values=Object.fromEntries(NUTRIENTS.map(k=>[k,items.some(p=>p.nutrients?.[k]!=null)?items.reduce((sum,p)=>sum+(p.nutrients?.[k]??0),0):null]));
  return `${nutrientRow(values,'Meal total')}${life.proposal?.changes.some(c=>!c.kind)?`<ul class="proposal-list">${life.proposal.changes.filter(c=>!c.kind).map(c=>`<li><b>${esc(c.label)}</b><span>${esc(c.after??'Unknown')}</span></li>`).join('')}</ul>`:''}<p class="help" role="status">${life.meal.error?esc(life.meal.error):life.proposal?'Ready for your diary. '+(items.some(p=>p.nutrients&&NUTRIENTS.some(k=>p.nutrients[k]==null))?'Some nutrition is unknown and excluded from known totals. ':'')+'Your saved records stay intact.':'Choose each food and enter its portion. Nothing has been saved.'}</p>${btn(life.busy?'Saving…':'Save to diary','proposal-save',!life.proposal||life.busy?'disabled':'')}${btn('Discard draft','proposal-dismiss',life.busy?'disabled':'',true)}`;
 }
 function mealReview(){return life.meal?`<section class="meal-review" aria-label="Meal review"><div class="section-head"><h2>Your meal</h2><span>${esc(dateLabel(life.meal.date))}</span></div><p class="help">Check the food match and portion. Raw and cooked weights use different nutrition.</p><fieldset class="meal-fields" ${life.busy?'disabled':''}>${life.meal.items.map(mealItem).join('')}</fieldset><div class="meal-footer">${mealFooter()}</div></section>`:'';}
 function updateMeal(index,{replace=false}={}){compileMeal();const el=document.querySelector(`.meal-item[data-meal-index="${index}"]`);if(el){if(replace)el.outerHTML=mealItem(life.meal.items[index],index);else el.querySelector('.meal-preview').innerHTML=mealPreview(life.meal.items[index]);}const footer=document.querySelector('.meal-footer');if(footer)footer.innerHTML=mealFooter();}
 async function action(name,b){
  if(name.startsWith('meal-')){
   const index=Number(b.dataset.index),item=life.meal?.items[index];if(!item)return true;
   if(name==='meal-remove'){life.meal.items.splice(index,1);if(!life.meal.items.length){life.meal=null;life.proposal=null;}else compileMeal();render();return true;}
   if(name==='meal-search'){item.query=document.querySelector(`[data-meal-query="${index}"]`).value.trim();item.choices=searchFoods(item.query,store.data);updateMeal(index,{replace:true});return true;}
   if(name==='meal-unknown'){item.foodId='unknown:'+item.query;item.choices=[];updateMeal(index,{replace:true});return true;}
   if(name==='meal-label'){foodForm(null,{name:item.query,quantity:item.amount?`${item.amount} ${item.unit}`:'',estimated:false},()=>{life.meal?.items.splice(index,1);if(!life.meal?.items.length){life.meal=null;life.proposal=null;}else compileMeal();});return true;}
  }
  if(['ask','inbox','life'].includes(name)){navigate(name);return true;}
  if(name==='reload'){await load();return true;}if(name==='wellbeing'){wellbeingForm();return true;}if(name==='task-add'){taskForm();return true;}if(name==='delivery-add'){deliveryForm();return true;}
  if(name==='task-toggle'){await save(s=>{const t=s.tasks.find(t=>t.id===b.dataset.id);if(t){t.status=t.status==='done'?'open':'done';t.completedAt=t.status==='done'?new Date().toISOString():null;t.updatedAt=new Date().toISOString();}});return true;}
  if(name==='delivery-toggle'){await save(s=>{const d=s.deliveries.find(d=>d.id===b.dataset.id);if(d){const done=['picked_up','delivered','cancelled'].includes(d.status);const previous=d.status;d.status=done?(d.previousStatus||'unknown'):'picked_up';if(!done)d.previousStatus=previous;d.completedAt=done?null:new Date().toISOString();}});return true;}
  if(name==='favorite'){await save(s=>{const i=s.favorites.indexOf(b.dataset.id);if(i<0)s.favorites.push(b.dataset.id);else s.favorites.splice(i,1);});return true;}
  if(name==='saved-facts'){const facts=Array.from({length:366},(_,i)=>factOfDay(shiftDate(state.date,-i))).filter((f,i,all)=>life.data.favorites.includes(f.id)&&all.findIndex(x=>x.id===f.id)===i);openSheet('Saved curiosities',facts.length?facts.map(f=>`<article class="insight-item"><h3>${esc(f.title)}</h3><p>${esc(f.text||f.body)}</p><a href="${esc(f.sourceURL||f.sourceUrl)}" target="_blank" rel="noopener noreferrer">Read the source ${arrow}</a></article>`).join(''):empty('Your collection starts here.','Save a daily fact to return to it later.'));return true;}
  if(name==='copy-code'){await navigator.clipboard.writeText(b.dataset.code);toast('Pickup code copied.');return true;}
  if(name==='inbox-sync'){await sync();return true;}if(name==='inbox-filter'){life.filter=b.dataset.filter;render();return true;}
  if(name==='gmail-connect'){const result=await post('inbox/connect',{});const url=new URL(result.url);if(url.origin!=='https://accounts.google.com')throw Error('Unexpected Gmail sign-in address.');location.assign(url.href);return true;}
  if(name==='gmail-disconnect'){await post('inbox/disconnect',{});life.emails=[];await load();toast('Gmail disconnected.');return true;}
  if(name==='notifications'){if(!('Notification' in window))throw Error('This browser does not support notifications.');const permission=await Notification.requestPermission();life.notifications=permission==='granted';toast(life.notifications?'Inbox notifications enabled while this tab is open.':'Notifications were not enabled.');return true;}
  if(name==='cleanup-example'){const input=document.querySelector('#cleanup-form textarea');input.value=b.dataset.query;life.cleanupQuery=input.value;return true;}
  if(name==='cleanup-apply'){const ids=[...document.querySelectorAll('[name=cleanup-id]:checked')].map(e=>e.value);if(!ids.length)throw Error('Select at least one message.');b.disabled=true;try{const operation=document.querySelector('#cleanup-operation').value,p=await post('inbox/cleanup',{stage:'preview',messageIds:ids,operation});await post('inbox/cleanup',{stage:'apply',previewToken:p.previewToken});if(operation==='read'){life.emails=life.emails.map(e=>ids.includes(e.id)?{...e,unread:false}:e);}else life.emails=life.emails.filter(e=>!ids.includes(e.id));closeSheet(true);toast('Selected mail updated in Gmail. Refreshing the scan.');await sync();}catch(e){document.querySelector('#cleanup-error').textContent=e.message;}finally{b.disabled=false;}return true;}
  if(name==='chatgpt'||name==='ai-setup'){chatGPTHandoff();return true;}if(name==='copy-handoff'){await navigator.clipboard.writeText(document.querySelector('#handoff-prompt').value);toast('Prompt copied. Paste into ChatGPT.');return true;}
  if(name==='prompt'){life.draft=b.dataset.prompt;render();document.querySelector('#assistant-message')?.focus();return true;}if(name==='photo-remove'){life.image=null;render();return true;}
  if(name==='proposal-dismiss'){if(life.busy)return true;life.proposal=null;life.meal=null;render();return true;}
  if(name==='proposal-save'){
   const proposal=life.proposal;if(!proposal||life.busy)return true;
   const commit=async()=>{life.busy=true;try{await store.save(data=>proposal.apply(data),'Log in-app health check-in');life.proposal=null;life.meal=null;life.draft='';life.image=null;const total=totals(dayFor(store.data,proposal.date));life.chat.push({role:'assistant',text:`Saved and verified in your diary for ${proposal.date}. Known daily totals: ${num(total.kcal)} kcal · ${num(total.protein)} g protein · ${num(total.carbs)} g carbs · ${num(total.fat)} g fat. Estimates and incomplete entries stay labelled.`});}finally{life.busy=false;}};
   if(store.connected){try{render();await commit();toast('Saved and verified in your diary.');}catch(e){life.chat.push({role:'assistant',text:e.message});}render();return true;}
   openSheet('Connect once to save your diary',`<form><p class="help">Your food and nutrition are already filled in. Connect browser editing to save this check-in for ${proposal.date}. Saved records stay intact.</p>${saveFooter('Connect & save to diary')}</form>`,()=>wireForm(commit));return true;
  }
  return false;
 }
 document.addEventListener('submit',async e=>{if(e.target.id==='assistant-form'||e.target.id==='cleanup-form'){e.preventDefault();try{if(e.target.id==='assistant-form')await send(e.target);else await cleanup(new FormData(e.target).get('query'));}catch(err){toast(err.message);}}});
 document.addEventListener('input',e=>{if(e.target.id==='assistant-message')life.draft=e.target.value;if(e.target.dataset.mealField==='amount'&&!life.busy){const index=Number(e.target.dataset.index),item=life.meal?.items[index];if(item){item.amount=e.target.value===''?null:Number(e.target.value);item.needsWeight=false;updateMeal(index);}}});
 document.addEventListener('change',e=>{const key=e.target.dataset.mealField;if(!key||key==='amount'||life.busy)return;const index=Number(e.target.dataset.index),item=life.meal?.items[index];if(!item)return;if(key==='foodId'&&item.unit.startsWith('p:')){item.unit='g';item.amount=null;}item[key]=e.target.value;updateMeal(index,{replace:key==='foodId'});});
 document.addEventListener('change',async e=>{if(e.target.id!=='checkin-photo')return;const f=e.target.files[0];if(!f)return;if(!['image/jpeg','image/png','image/webp'].includes(f.type)||f.size>5*1024*1024){toast('Choose a JPG, PNG, or WebP under 5 MB.');return;}const reader=new FileReader();reader.onload=()=>{life.image=reader.result;render();};reader.readAsDataURL(f);});
 return {life,load,action,healthTabs,wellbeingCard,setupBlock,view(view){return view==='dashboard'?overview():view==='inbox'?inbox():view==='life'?lifeView():view==='ask'?ask():view==='insights'?insights():null;}};
}
